def mean(values: list[float]) -> float:
    if not values:
        return 0.0
    return sum(values) / len(values)

def parse_port(text: str) -> int:
    port = int(text)
    if not 1 <= port <= 65535:
        raise ValueError('port out of range')
    return port

async def count_after(awaitable) -> int:
    items = await awaitable
    return len(items)

def positive(values):
    for value in values:
        if value > 0:
            yield value

template<typename T>
T clamp_value(T value, T lower, T upper) {
    if (value < lower) return lower;
    if (upper < value) return upper;
    return value;
}

LIMIT = 8

def normalized(value):
    return min(value, LIMIT)

def capped(value):
    return normalized(value)

def optional_int(text):
    try:
        return int(text)
    except ValueError:
        return None

def outer(value):
    def unused():
        raise RuntimeError('nested only')
        yield 99
    return value

int checked_divide(int a, int b, int *out) {
    if (!out || b == 0) return -1;
    *out = a / b;
    return 0;
}

bool take_last(std::vector<int>& values, int& out) {
    if (values.empty()) return false;
    out = values.back();
    values.pop_back();
    return true;
}

